150→// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
151→// on /full/current while preserving other checkpoints' transcripts in the tree.
152→func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
153→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
154→	if err := s.ensureRef(refName); err != nil {
155→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
156→	}
157→
158→	parentHash, rootTreeHash, err := s.getRefState(refName)
159→	if err != nil {
160→		return err
161→	}
162→
163→	basePath := opts.CheckpointID.Path() + "/"
164→	checkpointPath := opts.CheckpointID.Path()
165→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
166→
167→	// Read existing entries and replace transcript for this checkpoint only
168→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
169→	if err != nil {
170→		return err
171→	}
172→
173→	// Clear existing transcript entries at this session path before writing new ones
174→	for key := range entries {
175→		if strings.HasPrefix(key, sessionPath) {
176→			delete(entries, key)
177→		}
178→	}
179→
180→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, sessionPath, entries)
181→	if err != nil {
182→		return err
183→	}
184→
185→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
186→		return err
187→	}
188→
189→	// Splice into existing root tree (preserves other checkpoints' transcripts)
190→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
191→	if err != nil {
192→		return err
193→	}
194→
195→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
196→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
197→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
198→}
199→
200→// writeCommittedMain writes metadata entries to the /main ref.
201→// This includes session metadata and prompts — but NOT the raw transcript
202→// (full.jsonl) or content hash (content_hash.txt), which go to /full/current.
203→// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
204→func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
205→	refName := plumbing.ReferenceName(paths.V2MainRefName)
206→	if err := s.ensureRef(refName); err != nil {
207→		return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
208→	}
209→
210→	parentHash, rootTreeHash, err := s.getRefState(refName)
211→	if err != nil {
212→		return 0, err
213→	}
214→
215→	basePath := opts.CheckpointID.Path() + "/"
216→	checkpointPath := opts.CheckpointID.Path()
217→
218→	// Read existing entries at this checkpoint's shard path
219→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
220→	if err != nil {
221→		return 0, err
222→	}
223→
224→	// Build main session entries (metadata, prompts — no transcript or content hash)
225→	sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
226→	if err != nil {
227→		return 0, err
228→	}
229→
230→	// Splice entries into root tree
231→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
232→	if err != nil {
233→		return 0, err
234→	}
235→
236→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
237→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
238→		return 0, err
239→	}
240→	return sessionIndex, nil
241→}
242→
243→// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
244→// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
245→// Returns the session index used, for coordination with writeCommittedFullTranscript.
246→func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
247→	// Read existing summary to get current session count
248→	var existingSummary *CheckpointSummary
249→	metadataPath := basePath + paths.MetadataFileName
250→	if entry, exists := entries[metadataPath]; exists {
251→		existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
252→		if err == nil {
253→			existingSummary = existing
254→		}
255→	}
256→
257→	// Determine session index
258→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
259→
260→	// Write session files (metadata and prompts — no transcript or content hash)
261→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
262→	sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
263→	if err != nil {
264→		return 0, err
265→	}
266→
267→	// Build the sessions array
268→	var sessions []SessionFilePaths
269→	if existingSummary != nil {
270→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
271→		copy(sessions, existingSummary.Sessions)
272→	} else {
273→		sessions = make([]SessionFilePaths, 1)
274→	}
275→	sessions[sessionIndex] = sessionFilePaths
276→
277→	// Write root CheckpointSummary
278→	if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
279→		return 0, err
280→	}
281→	return sessionIndex, nil
282→}
283→
284→// writeMainSessionToSubdirectory writes a single session's metadata, prompts, and
285→// content hash to a session subdirectory (0/, 1/, 2/, … indexed by session order
286→// within the checkpoint). Unlike the v1 equivalent, this does NOT write the raw
287→// transcript (full.jsonl) — that goes to /full/current.
288→func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
289→	filePaths := SessionFilePaths{}
290→
291→	// Clear existing entries at this session path
292→	for key := range entries {
293→		if strings.HasPrefix(key, sessionPath) {
294→			delete(entries, key)
295→		}
296→	}
297→
298→	// Write prompts
299→	if len(opts.Prompts) > 0 {
300→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
301→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
302→		if err != nil {
303→			return filePaths, err
304→		}
305→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
306→			Name: sessionPath + paths.PromptFileName,
307→			Mode: filemode.Regular,
308→			Hash: blobHash,
309→		}
310→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
311→	}
312→
313→	// Write session metadata
314→	sessionMetadata := CommittedMetadata{
315→		CheckpointID:                opts.CheckpointID,
316→		SessionID:                   opts.SessionID,
317→		Strategy:                    opts.Strategy,
318→		CreatedAt:                   time.Now().UTC(),
319→		Branch:                      opts.Branch,
320→		CheckpointsCount:            opts.CheckpointsCount,
321→		FilesTouched:                opts.FilesTouched,
322→		Agent:                       opts.Agent,
323→		Model:                       opts.Model,
324→		TurnID:                      opts.TurnID,
325→		IsTask:                      opts.IsTask,
326→		ToolUseID:                   opts.ToolUseID,
327→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
328→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
329→		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart,
330→		TokenUsage:                  opts.TokenUsage,
331→		SessionMetrics:              opts.SessionMetrics,
332→		InitialAttribution:          opts.InitialAttribution,
333→		Summary:                     redactSummary(opts.Summary),
334→		CLIVersion:                  versioninfo.Version,
335→	}
336→
337→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
338→	if err != nil {
339→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
340→	}
341→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
342→	if err != nil {
343→		return filePaths, err
344→	}
345→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
346→		Name: sessionPath + paths.MetadataFileName,
347→		Mode: filemode.Regular,
348→		Hash: metadataHash,
349→	}
350→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
351→
352→	return filePaths, nil
353→}
354→
355→// writeContentHash computes and writes the content hash for already-redacted transcript bytes.
356→func (s *V2GitStore) writeContentHash(redactedTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
357→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(redactedTranscript))
358→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
359→	if err != nil {
360→		return err
361→	}
362→	entries[sessionPath+paths.ContentHashFileName] = object.TreeEntry{
363→		Name: sessionPath + paths.ContentHashFileName,
364→		Mode: filemode.Regular,
365→		Hash: hashBlob,
366→	}
367→	return nil
368→}
369→
370→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
371→// Transcripts accumulate across checkpoints — each write splices into the existing
372→// tree. When the ref reaches capacity, generation rotation (future work) archives
373→// the current ref and starts a fresh one.
374→//
375→// sessionIndex is the session slot (0-based), determined by the caller to stay
376→// consistent with the /main ref's session numbering.
377→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
378→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
379→	transcript := opts.Transcript
380→	if len(transcript) == 0 && opts.TranscriptPath != "" {
381→		var readErr error
382→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
383→		if readErr != nil {
384→			transcript = nil
385→		}
386→	}
387→	if len(transcript) == 0 {
388→		return nil // No transcript to write
389→	}
390→
391→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
392→	if err := s.ensureRef(refName); err != nil {
393→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
394→	}
395→
396→	parentHash, rootTreeHash, err := s.getRefState(refName)
397→	if err != nil {
398→		return err
399→	}
400→
401→	basePath := opts.CheckpointID.Path() + "/"
402→	checkpointPath := opts.CheckpointID.Path()
403→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
404→
405→	// Read existing entries at this checkpoint's shard path (accumulate, don't replace)
406→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
407→	if err != nil {
408→		return err
409→	}
410→
411→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
412→	if err != nil {
413→		return err
414→	}
415→
416→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
417→		return err
418→	}
419→
420→	// Splice into existing root tree (preserves other checkpoints' transcripts)
421→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
422→	if err != nil {
423→		return err
424→	}
425→
426→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
427→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
428→}
429→
430→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
431→// Returns the redacted transcript bytes so the caller can compute the content hash.
432→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
433→	// Redact secrets before chunking
434→	redacted, err := redact.JSONLBytes(transcript)
435→	if err != nil {
436→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
437→	}
438→
439→	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
440→	if err != nil {
441→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
442→	}
443→
444→	for i, chunk := range chunks {
445→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
446→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
447→		if err != nil {
448→			return nil, err
449→		}
450→		entries[chunkPath] = object.TreeEntry{
451→			Name: chunkPath,
452→			Mode: filemode.Regular,
453→			Hash: blobHash,
454→		}
455→	}
456→
457→	return redacted, nil
458→}
459→
460→// validateWriteOpts validates identifiers in WriteCommittedOptions.
461→func validateWriteOpts(opts WriteCommittedOptions) error {
462→	if opts.CheckpointID.IsEmpty() {
463→		return errors.New("invalid checkpoint options: checkpoint ID is required")
464→	}
465→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
466→		return fmt.Errorf("invalid checkpoint options: %w", err)
467→	}
468→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
469→		return fmt.Errorf("invalid checkpoint options: %w", err)
470→	}
471→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
472→		return fmt.Errorf("invalid checkpoint options: %w", err)
473→	}
474→	return nil
475→}
